      map['topic'] = Variable<String>(topic);
    }
    if (!nullToAbsent || imageIds != null) {
      map['image_ids'] = Variable<String>(imageIds);
    }
    map['origin'] = Variable<String>(origin);
    if (!nullToAbsent || relatedMemoryIds != null) {
      map['related_memory_ids'] = Variable<String>(relatedMemoryIds);
    }
    if (!nullToAbsent || relatedConversationId != null) {
      map['related_conversation_id'] = Variable<String>(relatedConversationId);
    }
    map['published_at'] = Variable<int>(publishedAt);
    if (!nullToAbsent || editedAt != null) {
      map['edited_at'] = Variable<int>(editedAt);
    }
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<String>(deletedAt);
    }
    return map;
  }

  PostsCompanion toCompanion(bool nullToAbsent) {
    return PostsCompanion(
      id: Value(id),
      content: Value(content),
      mood: mood == null && nullToAbsent ? const Value.absent() : Value(mood),
      topic: topic == null && nullToAbsent
          ? const Value.absent()
          : Value(topic),
      imageIds: imageIds == null && nullToAbsent
          ? const Value.absent()
          : Value(imageIds),
      origin: Value(origin),
      relatedMemoryIds: relatedMemoryIds == null && nullToAbsent
          ? const Value.absent()
          : Value(relatedMemoryIds),
      relatedConversationId: relatedConversationId == null && nullToAbsent
          ? const Value.absent()
          : Value(relatedConversationId),
      publishedAt: Value(publishedAt),
      editedAt: editedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(editedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
