      id: serializer.fromJson<String>(json['id']),
      content: serializer.fromJson<String>(json['content']),
      mood: serializer.fromJson<String?>(json['mood']),
      topic: serializer.fromJson<String?>(json['topic']),
      imageIds: serializer.fromJson<String?>(json['imageIds']),
      origin: serializer.fromJson<String>(json['origin']),
      relatedMemoryIds: serializer.fromJson<String?>(json['relatedMemoryIds']),
      relatedConversationId: serializer.fromJson<String?>(
        json['relatedConversationId'],
      ),
      publishedAt: serializer.fromJson<int>(json['publishedAt']),
