      relatedConversationId: data.relatedConversationId.present
          ? data.relatedConversationId.value
          : this.relatedConversationId,
      publishedAt: data.publishedAt.present
          ? data.publishedAt.value
          : this.publishedAt,
      editedAt: data.editedAt.present ? data.editedAt.value : this.editedAt,
      deletedAt: data.deletedAt.present ? data.deletedAt.value : this.deletedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Post(')
          ..write('id: $id, ')
          ..write('content: $content, ')
          ..write('mood: $mood, ')
          ..write('topic: $topic, ')
          ..write('imageIds: $imageIds, ')
          ..write('origin: $origin, ')
          ..write('relatedMemoryIds: $relatedMemoryIds, ')
          ..write('relatedConversationId: $relatedConversationId, ')
          ..write('publishedAt: $publishedAt, ')
          ..write('editedAt: $editedAt, ')
          ..write('deletedAt: $deletedAt')
          ..write(')'))
        .toString();
  }

